<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import { getOperationLogs, type OperationLog } from '@/api/admin'; import AdminSearchPanel from '@/components/AdminSearchPanel.vue'; import { useRoute } from 'vue-router'
const route=useRoute();const records=ref<OperationLog[]>([]);const loading=ref(true);const total=ref(0);const page=ref(1)
async function load(next=page.value){loading.value=true;page.value=next;try{const {data}=await getOperationLogs({page:page.value,pageSize:20,keyword:route.query.keyword,result:route.query.status});records.value=data.records;total.value=data.total}finally{loading.value=false}}
onMounted(()=>load());watch(()=>route.fullPath,()=>load())
</script>
<template><section class="content"><div class="title"><div><h1>操作日志</h1><p>追踪管理端关键操作、操作者和执行结果。</p></div></div><AdminSearchPanel/><el-table v-loading="loading" :data="records" stripe><el-table-column prop="createdAt" label="时间" min-width="170"/><el-table-column prop="operatorName" label="操作者" width="130"/><el-table-column prop="action" label="动作" width="90"/><el-table-column prop="requestPath" label="请求路径" min-width="260"/><el-table-column label="结果" width="90"><template #default="scope"><el-tag :type="scope.row.result==='SUCCESS'?'success':'danger'">{{scope.row.result==='SUCCESS'?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column prop="detail" label="详情" min-width="180"/></el-table><el-pagination v-if="total>20" v-model:current-page="page" layout="prev, pager, next" :page-size="20" :total="total" @current-change="load"/></section></template>
<style scoped>.content{padding:0}.title{margin-bottom:20px}.title h1{margin:0;color:var(--df-primary-950)}.title p{margin:8px 0 0;color:#77717e}.el-pagination{justify-content:center;margin-top:22px}</style>
